package com.example.starter.observation;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 创建 4x4 二值栅格观测请求：保存完整 16 格初始图，初始版本为 1。
 *
 * @param requestId     全局唯一请求标识（幂等去重键）
 * @param observationId 栅格观测唯一标识
 * @param operator      操作者标识（客户端来源），非空
 * @param cells         16 个格值，按行优先排列，取值 0 或 1；勾选格必须非空且四邻接连通
 */
public record CreateMaskRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 64) String observationId,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Size(min = 16, max = 16) List<@NotNull Integer> cells) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 栅格离线合并请求：客户端基于 baseVersion 提交修改后的完整 16 格全图，不是局部补丁。
 *
 * @param requestId   全局唯一请求标识（幂等去重键）
 * @param baseVersion 离线修改所基于的基版号
 * @param operator    操作者标识（客户端来源），非空
 * @param cells       客户端完整图：16 个格值，按行优先排列，取值 0 或 1
 */
public record MergeMaskRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotNull @Min(1) Integer baseVersion,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Size(min = 16, max = 16) List<@NotNull Integer> cells) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 删除栅格观测请求：expectedVersion 匹配当前版本时生成新版本墓碑；墓碑不参与合并。
 *
 * @param requestId       全局唯一请求标识（幂等去重键）
 * @param expectedVersion 期望删除时的当前版本号
 * @param operator        操作者标识（客户端来源），非空
 */
public record DeleteMaskRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotNull @Min(1) Integer expectedVersion,
        @NotBlank @Size(max = 128) String operator) {
}

package com.example.starter.observation;

import java.util.List;

/**
 * 栅格观测版本快照：元数据（版本号、基版、操作者、墓碑标记）与完整 16 格图。
 *
 * @param observationId 栅格观测唯一标识
 * @param version       版本号，从 1 开始
 * @param baseVersion   该版本合并所基于的基版号；创建版本与删除墓碑为 null
 * @param operator      写入该版本的操作者标识（客户端来源），非空
 * @param deleted       是否为删除墓碑：true 时 cells 为 null
 * @param cells         16 个格值，按行优先排列；删除墓碑版本为 null
 */
public record MaskSnapshot(
        String observationId,
        int version,
        Integer baseVersion,
        String operator,
        boolean deleted,
        List<Integer> cells) {
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 栅格观测响应：普通版本携带完整 16 格图与版本来源；删除墓碑只返回删除状态和版本，不带格值。
 *
 * @param observationId 栅格观测唯一标识
 * @param version       当前版本号
 * @param baseVersion   该版本合并所基于的基版号（创建版本为 null）
 * @param operator      写入该版本的操作者标识（客户端来源）
 * @param deleted       是否为删除墓碑
 * @param cells         16 个格值，按行优先排列；墓碑版本不返回
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record MaskResponse(
        String observationId,
        int version,
        Integer baseVersion,
        String operator,
        boolean deleted,
        List<Integer> cells) {

    /**
     * 由快照构造响应；墓碑版本自动省略格值。
     */
    public static MaskResponse of(MaskSnapshot snapshot) {
        if (snapshot.deleted()) {
            return new MaskResponse(snapshot.observationId(), snapshot.version(), null,
                    snapshot.operator(), true, null);
        }
        return new MaskResponse(snapshot.observationId(), snapshot.version(), snapshot.baseVersion(),
                snapshot.operator(), false, snapshot.cells());
    }
}

